import{_ as s}from"./chunks/architecture.BrenojrM.js";import{_ as p,C as A,o as a,c as h,a3 as r,b as e,w as d,a as i,E as o,a4 as n}from"./chunks/framework.CWYzGJW1.js";const f=JSON.parse('{"title":"組裝總覽與里程碑","description":"第二部的十個模組依相依關係由下往上組裝, 中途有三個里程碑, 每個里程碑都是可以獨立使用的系統.","frontmatter":{"description":"第二部的十個模組依相依關係由下往上組裝, 中途有三個里程碑, 每個里程碑都是可以獨立使用的系統."},"headers":[],"relativePath":"build/overview.md","filePath":"build/overview.md","lastUpdated":1793060541000}'),g={name:"build/overview.md"};function M(m,t,E,c,u,B){const l=A("Mermaid");return a(),h("div",null,[t[2]||(t[2]=r('<h1 id="組裝總覽與里程碑" tabindex="-1">組裝總覽與里程碑 <a class="header-anchor" href="#組裝總覽與里程碑" aria-label="Permalink to &quot;組裝總覽與里程碑&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本頁屬性</p><ul><li>等級: ● 必要</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-26</li><li>待查證: 記憶體與磁碟占用為研究 2 的推論值, 實機驗證前請視為推估值; 模型範例已更換, 數字須對照官方模型卡; 里程碑 3 圖中 Keycloak, OPA, ToolHive, gVisor, ModelAudit 的設定未實機驗證; 文中的類比為整理者所寫, 不代表技術上完全等同</li></ul></div><p><strong>結論</strong>: 第二部的十個模組依相依關係由下往上組裝, 中途有三個里程碑, 每個里程碑都是可以獨立使用的系統. 單人組到里程碑 1; 2 至 10 人且需要檢索, 組到里程碑 2; 多人, 多模型且有人每週維運 (並符合 M5.1 節條件), 才組到里程碑 3.</p><p>第二部像蓋房子: 先打地基 (M0 基礎環境), 再接水電 (M1 推論伺服器, 也就是實際跑模型的服務), 然後裝門窗 (M2 使用者介面), 之後才依需要加蓋房間. 每蓋到一個里程碑, 房子就能住人, 不必等全部蓋完. 多數個人與小團隊停在里程碑 1 或 2 就夠用.</p><div class="tip custom-block"><p class="custom-block-title">本章常見名詞</p><table tabindex="0"><thead><tr><th>詞</th><th>意思</th></tr></thead><tbody><tr><td>模組</td><td>第二部的一個組裝單元, 編號 M0 至 M9, 每個模組完成一件事</td></tr><tr><td>里程碑</td><td>完成一組模組後, 系統可以獨立使用的階段</td></tr><tr><td>容器 (container) 與 Docker</td><td>把程式和它需要的檔案包成一包, 在主機上隔開執行; Docker 是最常用的容器工具</td></tr><tr><td>VM (虛擬機)</td><td>在一台實體主機上切出來的獨立電腦, 有自己的作業系統</td></tr><tr><td>反向代理 (reverse proxy)</td><td>站在服務前面的接待櫃台, 統一接收使用者連線, 再轉給後面的服務</td></tr><tr><td>閘道 (gateway)</td><td>模型或工具前面的關卡, 統一管帳號, 金鑰, 用量與紀錄</td></tr><tr><td>RAG (檢索增強生成)</td><td>先從文件找出相關段落, 再交給模型回答</td></tr><tr><td>向量庫 (vector database)</td><td>存放文件段落「意思座標」的資料庫, 用來找意思相近的段落</td></tr><tr><td>MCP</td><td>讓模型呼叫外部工具的共通協定</td></tr><tr><td>沙箱 (sandbox)</td><td>與主機隔開, 執行不可信程式碼的封閉環境</td></tr></tbody></table><p>完整詞彙見<a href="/lanai-handbook/ref/glossary">術語對照</a>.</p></div><table tabindex="0"><thead><tr><th>里程碑</th><th>完成的模組</th><th>適用</th><th>建議硬體等級</th><th>額外占用 (推論)</th></tr></thead><tbody><tr><td>1. 能對話 (最小安全組合)</td><td>M0 至 M2</td><td>單人, 單機</td><td>A 至 F</td><td>介面約 0.5 至 1.5GB 記憶體; 磁碟約 2 至 5GB (不含模型)</td></tr><tr><td>2. 能查文件, 能多人用 (標準組合)</td><td>再加 M3, M4, M6; M5 閘道與 Keycloak 依 M5.1 節的條件才加</td><td>家庭或小團隊 2 至 10 人</td><td>B (12GB 以上), D, E; C 級 32GB 以上</td><td>嵌入模型約 0.6 至 1.2GB; 向量庫約 1 至 2GB; 磁碟約 10 至 30GB</td></tr><tr><td>3. 能動手做事 (進階組合)</td><td>再加 M7 至 M9</td><td>多人, 多模型, 含閘道, 代理與沙箱</td><td>F</td><td>閘道加上它使用的 PostgreSQL 資料庫約 1 至 2GB; 磁碟約 50 至 100GB</td></tr></tbody></table><p>資料來源: 研究 2 (2026-10-26), 占用值由各元件公開資料加總推算, 信心: 中. 嵌入模型一欄: EmbeddingGemma 的 Ollama 標籤頁標示 622MB; multilingual-e5-large-instruct 約 6 億參數 (Hugging Face 模型卡), 以每參數 2 位元組推估約 1.2GB (推論).</p><h2 id="組裝順序與相依關係" tabindex="-1">組裝順序與相依關係 <a class="header-anchor" href="#組裝順序與相依關係" aria-label="Permalink to &quot;組裝順序與相依關係&quot;">​</a></h2><p>模組之間有先後關係: 後面的模組要用到前面模組提供的服務, 順序顛倒時會裝不起來, 或少了應有的保護. 下表列出每個模組要先完成哪些模組.</p><table tabindex="0"><thead><tr><th>模組</th><th>需要先完成</th><th>為什麼排在這裡</th></tr></thead><tbody><tr><td>M0 基礎環境</td><td>無</td><td>網段, 主機與備份要先就位, 之後每個模組都放在這個環境裡</td></tr><tr><td>M1 推論伺服器</td><td>M0</td><td>沒有模型就沒有服務, 先確認硬體跑得動</td></tr><tr><td>M2 使用者介面與反向代理</td><td>M1</td><td>介面要連到推論伺服器才能驗收</td></tr><tr><td>M3 模型入庫與存放</td><td>M0</td><td>模型變多之前, 先把來源與檢查流程固定下來</td></tr><tr><td>M4 檢索 (RAG)</td><td>M1, M2</td><td>嵌入模型跑在推論伺服器, 使用者在介面中提問</td></tr><tr><td>M5 模型閘道與身分驗證</td><td>M1, M2</td><td>多人共用時, 介面改經閘道連模型, 帳號改由身分驗證伺服器管理</td></tr><tr><td>M6 可觀測, 稽核與評估</td><td>M1, M2 (有 M5 時以閘道為紀錄集中點)</td><td>測試集從里程碑 1 就可以開始建; 部署 M5 後, 閘道是蒐集呼叫紀錄的集中點</td></tr><tr><td>M7 工具與沙箱</td><td>M5, M6</td><td>工具會改變系統狀態, 先有紀錄才開放</td></tr><tr><td>M8 代理與治理</td><td>M7</td><td>代理只能透過工具閘道動手, 所以工具要先就位</td></tr><tr><td>M9 流程自動化</td><td>M5, M7</td><td>n8n 只經模型閘道與工具閘道對外, 不直接保存金鑰</td></tr></tbody></table><h2 id="里程碑-1-能對話-最小安全組合" tabindex="-1">里程碑 1: 能對話 (最小安全組合) <a class="header-anchor" href="#里程碑-1-能對話-最小安全組合" aria-label="Permalink to &quot;里程碑 1: 能對話 (最小安全組合)&quot;">​</a></h2><p>里程碑 1 的目標是讓一個人在自己的電腦上和模型對話, 對話內容不離開這台電腦. 這是最小, 也最容易維護的組合.</p><p><strong>元件</strong>: 推論伺服器 (llama.cpp 或 Ollama, 見 M1), 加上一個介面 (見 M2). 等級 A 與 C 建議用 AnythingLLM 桌面版 (在單機上對話與查文件的桌面應用程式), 其他等級用 Open WebUI (在瀏覽器中使用的對話介面) 單一容器. 不加閘道, 代理框架與 MCP.</p><p><strong>啟動順序</strong>: 推論引擎 → 介面.</p><p>下圖是里程碑 1 的連線關係: 瀏覽器只連本機的介面, 介面再把問題轉給推論伺服器.</p>',15)),(a(),e(n,null,{default:d(()=>[o(l,{id:"mermaid-357",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%80%8F%E8%A6%BD%E5%99%A8%20%2F%20%E6%A1%8C%E9%9D%A2%20App%22%5D%20--%3E%7C%22http%3A%2F%2F127.0.0.1%3A3000%22%7C%20B%5B%22Open%20WebUI%20%E6%88%96%20AnythingLLM%22%5D%0A%20%20B%20--%3E%20C%5B%22Ollama%20%2F%20llama-server%22%5D%0A%20%20B%20---%20D%5B%22%E6%9C%AC%E6%A9%9F%E8%B3%87%E6%96%99%E5%8D%B7%3A%20%E5%B0%8D%E8%A9%B1%2C%20%E8%A8%AD%E5%AE%9A%22%5D%0A%20%20D%20--%3E%20E%5B%22%E6%AF%8F%E9%80%B1%E5%82%99%E4%BB%BD%22%5D%0A%20%20N%5B%22%E5%B0%8D%E5%A4%96%3A%20%E7%84%A1%E9%96%8B%E6%94%BE%E9%80%A3%E6%8E%A5%E5%9F%A0%22%5D%3A%3A%3Anote%0A%20%20classDef%20note%20stroke-dasharray%3A%204%204%0A"})]),fallback:d(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=r('<p><strong>里程碑 1 檢核表</strong></p><p>127.0.0.1 是電腦稱呼自己的位址; 服務只綁這個位址時, 同一台電腦以外的裝置都連不進來.</p><ul><li>[ ] 所有服務只綁 127.0.0.1, Docker Engine 為 28.0.0 以上版本 (見 M0.3 節)</li><li>[ ] 映像或安裝版本已記錄並鎖定</li><li>[ ] 介面已設管理者密碼, 並關閉公開註冊</li><li>[ ] 每週備份資料卷</li><li>[ ] 每週檢查一次安全公告, 每月評估一次是否升級 (見 O2, O3)</li><li>[ ] 不在介面中存放雲端 API 金鑰, 或只放低額度金鑰</li></ul><p>用 Docker 執行介面時的連接埠與位址設定, 見 M2.</p><h2 id="里程碑-2-能查文件-能多人用-標準組合" tabindex="-1">里程碑 2: 能查文件, 能多人用 (標準組合) <a class="header-anchor" href="#里程碑-2-能查文件-能多人用-標準組合" aria-label="Permalink to &quot;里程碑 2: 能查文件, 能多人用 (標準組合)&quot;">​</a></h2><p>里程碑 2 加上兩件事: 讓模型回答時參考自己的文件, 以及讓家人或同事透過內網共用同一台主機. 可以想成把個人書桌換成小型共用圖書室: 書 (文件) 要先上架編目, 每位讀者也要有自己的借書證 (帳號).</p><p><strong>元件</strong>:</p><ul><li>推論引擎, 搭配 llama-swap (需要多模型輪替時)</li><li>介面: Open WebUI 或 LibreChat (兩者都是瀏覽器中的對話介面, 支援多使用者帳號)</li><li>嵌入模型: EmbeddingGemma-300m, multilingual-e5-large-instruct 或 nomic-embed-text-v2-moe (見 M4.2 節)</li><li>向量庫: 介面內建的, 或 Qdrant (獨立執行的向量資料庫服務)</li><li>文件解析: Docling</li><li>評估: promptfoo 測試集 (M6)</li><li>網路: 只限內網 (辦公室或機房的區域網路)</li></ul><p><strong>啟動順序</strong>: 推論引擎 / llama-swap → 向量庫 → 介面 → (排程) 文件解析與匯入 → promptfoo 驗證.</p><p>llama-swap 負責依請求切換要載入的模型; Docling 把 PDF 等文件轉成文字; promptfoo 用固定題目檢查升級後回答品質有沒有變差. 下圖是里程碑 2 在單機上的連線關係: 所有元件以 Docker 跑在同一台主機, 只有介面經反向代理對內網開放, Qdrant 與 llama-swap 只在內部 Docker 網路中, 不對外發布連接埠. 在 Proxmox VE 上分成多台 VM 時, 連線改依 <a href="/lanai-handbook/build/m0-foundation">M0.2 節</a>的對照表.</p>',10)),(a(),e(n,null,{default:d(()=>[o(l,{id:"mermaid-451",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%AE%B6%E4%BA%BA%20%2F%20%E5%90%8C%E4%BA%8B%E8%A3%9D%E7%BD%AE%22%5D%20--%3E%7C%22%E5%85%A7%E7%B6%B2%20HTTPS%22%7C%20H%5B%22%E4%B8%BB%E6%A9%9F%20192.168.x.y%22%5D%0A%20%20H%20--%3E%20W%5B%22Open%20WebUI%20%2F%20LibreChat%22%5D%0A%20%20H%20--%3E%20Q%5B%22Qdrant%20%3A6333%22%5D%0A%20%20H%20--%3E%20D%5B%22Docling%20%E6%89%B9%E6%AC%A1%22%5D%0A%20%20W%20--%3E%7C%22%E5%85%A7%E9%83%A8%20Docker%20%E7%B6%B2%E8%B7%AF%2C%20%E4%B8%8D%E5%B0%8D%E5%A4%96%22%7C%20S%5B%22llama-swap%20%3A8080%22%5D%0A%20%20S%20--%3E%20L%5B%22llama-server%3A%20%E5%B0%8D%E8%A9%B1%E6%A8%A1%E5%9E%8B%20%2F%20%E5%B5%8C%E5%85%A5%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20N%5B%22%E5%85%AC%E7%B6%B2%3A%20%E7%84%A1%E9%80%A3%E6%8E%A5%E5%9F%A0%E8%BD%89%E7%99%BC%22%5D%3A%3A%3Anote%0A%20%20classDef%20note%20stroke-dasharray%3A%204%204%0A"})]),fallback:d(()=>[...t[1]||(t[1]=[i(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=r('<p><strong>里程碑 2 檢核表 (在里程碑 1 之上, 另加)</strong>:</p><ul><li>[ ] 以主機防火牆限定可連入的內網網段</li><li>[ ] 每位使用者使用個別帳號</li><li>[ ] RAG 文件來源只限可信資料夾 (對應 OWASP LLM05, LLM09 與 ASI06, 見 K6.4 節)</li><li>[ ] 升級前先跑 promptfoo 測試集</li><li>[ ] <code>.env</code> 權限設為 600 (<code>.env</code> 是存放密碼與金鑰的設定檔, 600 表示只有檔案擁有者能讀寫)</li></ul><h2 id="里程碑-3-能動手做事-進階組合-◇" tabindex="-1">里程碑 3: 能動手做事 (進階組合) ◇ <a class="header-anchor" href="#里程碑-3-能動手做事-進階組合-◇" aria-label="Permalink to &quot;里程碑 3: 能動手做事 (進階組合) ◇&quot;">​</a></h2><p>里程碑 3 讓模型不只回答, 還能透過工具實際操作系統, 例如查詢紀錄或開工單. 可以想成從「會回答問題的顧問」變成「能動手辦事的助理」: 能做的事越多, 越需要權限管控, 紀錄與人工確認.</p><p><strong>使用條件</strong>: 有人能每週維運, 且符合 M5.1 節列出的閘道條件. 若不符, 請停在里程碑 2.</p><p><strong>元件</strong>: 標準組合全部, 加上:</p><ul><li>推論伺服器: vLLM (以 GPU 為主, 能同時處理多個請求的推論伺服器; 多人同時使用時, 吞吐量明顯高於 llama.cpp 與 Ollama)</li><li>閘道: LiteLLM 或 Bifrost 擇一 (兩者都是模型閘道, 統一轉送模型請求並管理金鑰與用量), 以映像摘要值 (digest) 鎖定版本</li><li>反向代理: Nginx 或 Caddy (兩者都是網頁伺服器, 在這裡負責接收連線, 處理 HTTPS 並轉給後面的服務), 只接受內網連線</li><li>身分驗證 (可選): Keycloak (集中管理帳號與登入的身分驗證伺服器), 以 OIDC (單一登入常用的標準協定) 提供單一登入</li><li>代理: LangGraph 程式庫 (把代理的各個步驟串成流程並保存狀態), 嵌入自己撰寫的服務; 搭配 OPA 政策引擎 (依固定規則判定每個動作能不能執行)</li><li>隔離模型: 自建程式加本地模型, 專門讀取不可信內容, 不給任何工具</li><li>工具閘道: MCP gateway (ToolHive 等; 統一執行, 管理 MCP 伺服器並控管哪些工具能被呼叫), 加上少量已審核, 已容器化的 MCP 伺服器</li><li>程式碼沙箱: Docker 加 gVisor (在容器與主機核心之間多加一層隔離)</li><li>模型入庫檢查 (ModelAudit 等掃描模型檔的工具) 與 NFS (讓多台主機透過網路共用 NAS 上檔案的協定) 唯讀的模型存放區</li><li>可選: n8n (規則固定的流程自動化), Langfuse (記錄每次模型呼叫的過程與結果, 供追查與評估; 另備至少 12GB 記憶體給它使用的 ClickHouse 與 Redis 等資料庫), OTel Collector (收集各服務的紀錄與指標並轉送), Prometheus (定期收集數值指標) 與 Grafana (把指標畫成儀表板), Prompt Guard 2 22M (偵測提示注入的小型分類模型)</li></ul><p><strong>啟動順序</strong>: PostgreSQL / Redis → 推論伺服器 / llama-swap → 閘道 → 向量庫 → OPA → MCP gateway 與 MCP 伺服器 (容器) → 代理服務 → n8n → Keycloak → 介面 → 反向代理 → 可觀測性.</p><p><img src="'+s+'" alt="里程碑 3 的完整部署架構"></p><p>這張圖就是<a href="/lanai-handbook/start/map">架構地圖</a>上的終點. 珊瑚色元件接觸不可信內容, 紫色是可信控制區, 米色是基礎設施; 粗框是實體主機, 細框是 VM, 點線框是設備. 方塊上方是要安裝的軟體, 下方是角色.</p><p><strong>部署分區</strong>: Proxmox VE 是在一台實體主機上建立與管理多台 VM 的開源平台. 這裡以 VM 劃分信任區, 接觸不可信內容的元件一律放 VM, 不放 LXC 容器 (LXC 與主機共用核心, 隔離較弱; 推論, 信心: 中).</p><table tabindex="0"><thead><tr><th>VM 區</th><th>放什麼</th><th>網路限制</th></tr></thead><tbody><tr><td>入口區</td><td>反向代理, 介面, Keycloak, Docling, Qdrant</td><td>只接受內網使用者連線</td></tr><tr><td>控制區</td><td>LangGraph, OPA</td><td>只能連閘道區與隔離區</td></tr><tr><td>隔離區</td><td>隔離模型</td><td>只能連 LiteLLM, 不持有任何工具憑證</td></tr><tr><td>閘道區</td><td>LiteLLM, MCP gateway</td><td>唯一保存 API 金鑰, 唯一能對外連線的區</td></tr><tr><td>工具區</td><td>MCP 伺服器, 程式碼沙箱</td><td>沙箱無網路; MCP 伺服器只能連指定系統</td></tr><tr><td>推論區</td><td>vLLM (GPU 直通)</td><td>只接受閘道區連線</td></tr><tr><td>稽核區</td><td>Langfuse, OTel Collector, Prometheus</td><td>只接收紀錄, 轉送既有 SIEM (集中分析資安紀錄的系統)</td></tr><tr><td>自動化區</td><td>n8n</td><td>只能連閘道區 (LiteLLM, MCP gateway)</td></tr></tbody></table><p>資料來源: 分區方式整理自 2026-10 的藍隊代理架構模擬與研究 2, 屬推論, 信心: 中. 實際部署前請以自己的網段與防火牆規則驗證.</p><p><strong>里程碑 3 檢核表 (在里程碑 2 之上, 另加)</strong>:</p><ul><li>[ ] 閘道與 MCP 映像以摘要值鎖定, 並訂閱 GitHub Security Advisories (GitHub 上發布漏洞公告的資料庫)</li><li>[ ] 閘道管理端點只限管理者 IP</li><li>[ ] 每位使用者或每個應用各一把虛擬金鑰, 並設用量上限</li><li>[ ] 代理的寫入與刪除動作需要人工確認</li><li>[ ] 沙箱無網路, 並有資源上限</li><li>[ ] MCP 工具描述變更時重新審核</li><li>[ ] 金鑰輪替流程已準備, 並演練過一次</li><li>[ ] 推論伺服器只接受閘道連線</li><li>[ ] 模型檔入庫前掃描並記錄雜湊值, 推論伺服器以唯讀方式掛載</li><li>[ ] n8n 不保存外部系統金鑰, 工具一律經 MCP gateway 呼叫</li></ul><h2 id="硬體等級對應" tabindex="-1">硬體等級對應 <a class="header-anchor" href="#硬體等級對應" aria-label="Permalink to &quot;硬體等級對應&quot;">​</a></h2><p>硬體等級 A 至 F 的判斷方式見<a href="/lanai-handbook/start/usage">使用說明</a>的「硬體自我檢測」. 下表列出各等級建議組到哪個組合.</p><table tabindex="0"><thead><tr><th>等級</th><th>建議架構</th><th>備註</th></tr></thead><tbody><tr><td>A 無獨顯筆電</td><td>最小組合 (AnythingLLM 桌面版)</td><td>RAG 只用小型嵌入模型; 不跑代理</td></tr><tr><td>B 8 至 12GB 顯示卡</td><td>最小組合, 或精簡標準組合</td><td>嵌入模型放 CPU, 保留顯示記憶體</td></tr><tr><td>C Apple Silicon</td><td>16GB 用最小組合; 32GB 以上可用標準組合</td><td>依統一記憶體決定</td></tr><tr><td>D 16GB 顯示卡</td><td>標準組合</td><td>llama-swap 輪替對話與嵌入模型</td></tr><tr><td>E</td><td>標準組合; 小團隊可加 LangGraph</td><td>使用 Langfuse 須確認系統記憶體 32GB 以上</td></tr><tr><td>F</td><td>進階組合</td><td>有人能每週維運時才採用</td></tr></tbody></table><p>資料來源: 研究 2 (內部研究紀錄, 非公開來源), 屬推論, 信心: 中.</p><h2 id="參考來源" tabindex="-1">參考來源 <a class="header-anchor" href="#參考來源" aria-label="Permalink to &quot;參考來源&quot;">​</a></h2><p>本頁的里程碑劃分, 組裝順序, VM 分區與硬體等級對應, 是整理者依各模組內容所做的設計與判斷 (信心標示見各表下方), 其中引用的內部研究紀錄為非公開來源, 沒有公開連結. 各元件的版本, 參數, 指令與漏洞紀錄, 來源列在對應模組章 (M0 至 M9) 的「參考來源」與<a href="/lanai-handbook/ref/versions">版本與漏洞頁</a>; 本頁另可查證的外部事實如下.</p><ul><li>嵌入模型占用: <a href="https://huggingface.co/google/embeddinggemma-300m" target="_blank" rel="noreferrer">EmbeddingGemma-300m 模型卡 (Hugging Face)</a>, <a href="https://ollama.com/library/embeddinggemma/tags" target="_blank" rel="noreferrer">EmbeddingGemma Ollama 標籤頁</a> (622MB), <a href="https://huggingface.co/intfloat/multilingual-e5-large-instruct" target="_blank" rel="noreferrer">multilingual-e5-large-instruct 模型卡 (Hugging Face)</a> (約 6 億參數, 約 1.2GB 為整理者以每參數 2 位元組推估).</li><li>「只綁 127.0.0.1」: <a href="https://docs.docker.com/engine/network/port-publishing/" target="_blank" rel="noreferrer">Docker 文件: Port publishing and mapping</a> 說明發布容器連接埠後服務對外部開放, 加上 127.0.0.1 才限制為主機本機存取.</li><li>檢核表中的 OWASP LLM05, LLM09 與 ASI06, 對應見 K6.4 節的「參考來源」.</li><li>文中的類比 (蓋房子, 共用圖書室, 顧問與助理): 整理者所寫, 無外部來源, 不應當作技術定義引用.</li><li>尚無公開來源: 各里程碑的記憶體與磁碟占用 (除嵌入模型外) 為整理者推估, Langfuse 記憶體需求見 M6, VM 與 LXC 隔離強度比較為整理者判斷 (推論, 信心: 中), 實機驗證前請視為推估值.</li></ul>',22))])}const C=p(g,[["render",M]]);export{f as __pageData,C as default};
